export type ValueCurve = zod.input<typeof ValueCurve>;
export type ValueCurveOutput = zod.output<typeof ValueCurve>;

export const PollutantType = zod
  .enum([
    "CO2",
    "CO2E",
    "CH4",
    "N2O",
    "NOX",
    "SO2",
    "CO",
    "VOC",
    "PM25",
    "PM10",
    "HG",
    "HAP",
    "CUSTOM",
  ])
  .describe(
    "Pollutant an emission rate is reported for, spanning greenhouse gases (`CO2`, `CO2E`, `CH4`, `N2O`), criteria pollutants (`NOX`, `SO2`, `CO`, `VOC`, `PM25`, `PM10`), and toxics (`HG`, `HAP`), with `CUSTOM` for a user-defined pollutant.",
  );

export type PollutantType = zod.input<typeof PollutantType>;
export type PollutantTypeOutput = zod.output<typeof PollutantType>;

export const EmissionBasis = zod
  .enum(["FUEL_INPUT", "POWER_OUTPUT"])
  .describe(
    "What an emission rate is measured against: `FUEL_INPUT` for mass per unit of heat input, `POWER_OUTPUT` for mass per unit of electrical output. The choice constrains the accompanying energy unit — a heat unit for `FUEL_INPUT`, `MWH` for `POWER_OUTPUT`.",
  );

export type EmissionBasis = zod.input<typeof EmissionBasis>;
export type EmissionBasisOutput = zod.output<typeof EmissionBasis>;

export const MassUnit = zod
  .enum(["KG", "LB", "SHORT_TON", "METRIC_TON"])
  .describe(
    "Mass unit an emission quantity is reported in: kilograms, pounds, short tons (2000 lb), or metric tons (1000 kg).",
  );

export type MassUnit = zod.input<typeof MassUnit>;
export type MassUnitOutput = zod.output<typeof MassUnit>;

export const EnergyUnit = zod
  .enum(["MMBTU", "GJ", "MWH"])
  .describe(
    "Energy unit forming the denominator of an emission rate: `MMBTU` or `GJ` for a fuel-input basis, `MWH` for a power-output basis.",
  );

export type EnergyUnit = zod.input<typeof EnergyUnit>;
export type EnergyUnitOutput = zod.output<typeof EnergyUnit>;

